using System.ComponentModel;
using Microsoft.Extensions.AI;

// --- Tool Definitions ---

var notes = new List<string>();

var searchTool = AIFunctionFactory.Create(
    [Description("Searches the web for information on a given query and returns relevant results.")]
    (string query) =>
    {
        // Simulated web search results based on query keywords
        var results = new List<string>();

        if (query.Contains("quantum", StringComparison.OrdinalIgnoreCase))
        {
            results.Add("Quantum computing uses qubits that can exist in superposition, enabling parallel computation.");
            results.Add("Major players include IBM (127-qubit Eagle), Google (Sycamore), and IonQ (trapped-ion approach).");
            results.Add("Potential applications: cryptography, drug discovery, optimization problems, and materials science.");
        }
        else if (query.Contains("AI", StringComparison.OrdinalIgnoreCase) || query.Contains("artificial intelligence", StringComparison.OrdinalIgnoreCase))
        {
            results.Add("Large language models like GPT-4 and Claude demonstrate emergent reasoning capabilities.");
            results.Add("AI agents can now use tools, plan multi-step tasks, and collaborate with other agents.");
            results.Add("Key concerns include alignment, hallucination, and energy consumption of training runs.");
        }
        else
        {
            results.Add($"Search results for '{query}': Found several articles discussing recent developments and research.");
            results.Add($"Experts in {query} suggest rapid progress is expected in the coming years.");
        }

        return string.Join("\n", results);
    },
    "search_web");

var noteToolSave = AIFunctionFactory.Create(
    [Description("Saves a research note for later use in the final summary. Use this to record key findings.")]
    (string note) =>
    {
        notes.Add(note);
        return $"Note saved. You now have {notes.Count} note(s).";
    },
    "save_note");

var noteToolRead = AIFunctionFactory.Create(
    [Description("Reads all previously saved research notes.")]
    () =>
    {
        if (notes.Count == 0)
            return "No notes saved yet.";
        return string.Join("\n---\n", notes.Select((n, i) => $"[{i + 1}] {n}"));
    },
    "read_notes");

// --- Agent Setup ---

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "test-key";
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o";
var endpoint = Environment.GetEnvironmentVariable("OPENAI_ENDPOINT");

IChatClient innerClient;
if (endpoint is not null)
{
    var openAiClient = new OpenAI.OpenAIClient(new System.ClientModel.ApiKeyCredential(apiKey),
        new OpenAI.OpenAIClientOptions { Endpoint = new Uri(endpoint) });
    innerClient = openAiClient.GetChatClient(model).AsIChatClient();
}
else
{
    innerClient = new OpenAI.OpenAIClient(apiKey).GetChatClient(model).AsIChatClient();
}

IChatClient agent = new ChatClientBuilder(innerClient)
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions
{
    Tools = [searchTool, noteToolSave, noteToolRead]
};

// --- Run the Research Agent ---

var topic = args.Length > 0 ? string.Join(" ", args) : "quantum computing";

Console.WriteLine($"🔬 Research Agent Starting...");
Console.WriteLine($"📋 Topic: {topic}");
Console.WriteLine(new string('─', 50));

var messages = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to research a topic thoroughly by:
        1. Searching the web for relevant information (make 2-3 searches with different queries)
        2. Saving key findings as notes using the save_note tool
        3. Reading your notes back to review them
        4. Providing a comprehensive summary of your research

        Be methodical: search, take notes on important findings, then summarize.
        """),
    new(ChatRole.User, $"Please research the following topic and provide a summary: {topic}")
};

Console.WriteLine("\n🤖 Agent is researching...\n");

var response = await agent.GetResponseAsync(messages, chatOptions);

Console.WriteLine(new string('─', 50));
Console.WriteLine("📝 RESEARCH SUMMARY");
Console.WriteLine(new string('─', 50));
Console.WriteLine(response.Text);
Console.WriteLine(new string('─', 50));
Console.WriteLine($"\n📌 Notes collected: {notes.Count}");
foreach (var (note, idx) in notes.Select((n, i) => (n, i)))
{
    Console.WriteLine($"  [{idx + 1}] {note}");
}

